def art_prompt(art_style: str | None) -> dict[str, str]:
    return ART_STYLE_PROMPTS.get((art_style or "pixel").lower(), _FALLBACK_PROMPT)


def build_config_table(
    style: StylePreset,
    *,
    project_name: str = "图标工厂",
    template_key: str = "full",
    art_style: str | None = None,
    palette_key: str | None = None,
    palette_label: str | None = None,
) -> str:
    """生成「当前配置」表，确保页面上的五项配置同步进 AGENTS。"""
    prompt = art_prompt(art_style)
    template_label = TEMPLATES.get(template_key, {}).get("label", template_key)
    palette_value = (
        f"{palette_label or palette_key}（`{palette_key}`）"
        if palette_key
        else "未指定（仅列出色板库）"
    )
    rows = [
        ("项目名", project_name),
        ("风格预设", f"{style.name}（`{style.key}`）"),
        ("文档模板", f"{template_label}（`{template_key}`）"),
        ("画法风格", f"{prompt['name']}（`{(art_style or 'pixel').lower()}`）"),
        ("色板", palette_value),
    ]
    lines = ["## 当前配置", "", "| 项 | 取值 |", "|---|---|"]
    lines.extend(f"| {key} | {value} |" for key, value in rows)
    return "\n".join(lines)


